def test_pairplot_no_numeric_columns_raises_typed_valueerror():
    """Auto-detect over an all-string frame yields rows=cols=[]; the failure
    must be a legible ValueError, not an IndexError/ZeroDivisionError."""
    with pytest.raises(ValueError):
        fm.pairplot(pl.DataFrame({"s": ["x", "y"]})).to_svg()


def test_pairplot_empty_vars_list_raises_valueerror(df):
    """vars=[] passes RepeatChart's `row is None` validation (an empty list is
    not None) — the zero-panel grid must still fail with ValueError."""
    with pytest.raises(ValueError):
        fm.pairplot(df, vars=[]).to_svg()


def test_pairplot_dropna_all_rows_raises_valueerror():
    """dropna=True dropping every row -> all-empty composition raises (the
    documented Phase-B contract), never a blank grid or a Rust panic."""
    dfz = pl.DataFrame({"a": [None, None], "b": [1.0, 2.0], "grp": ["p", "q"]}).with_columns(
        pl.col("a").cast(pl.Float64)
    )
    with pytest.raises(ValueError):
        fm.pairplot(dfz, vars=["a", "b"], dropna=True).to_svg()


