def test_pairplot_encode_color_legend_none_suppresses_figure_legend(df):
    svg = fm.pairplot(
        df, vars=["a", "b"], hue="grp", encode={"color": fm.Color("grp", legend=None)}
    ).to_svg()
    texts = _legend_texts(svg)
    assert "grp" not in texts, f"legend=None on every leaf must suppress the figure legend: {texts}"
    assert texts.count("p") == 0 and texts.count("q") == 0


def test_jointplot_encode_color_legend_none_suppresses_figure_legend(df):
    svg = fm.jointplot(
        df, x="a", y="b", hue="grp", encode={"color": fm.Color("grp", legend=None)}
    ).to_svg()
    texts = _legend_texts(svg)
    assert "grp" not in texts


# ---------------------------------------------------------------------------
# Auto-tooltip interaction with explicit tooltip= on layered charts.
# Targets: SpecBuildMixin._inject_auto_tooltips (per-layer injection,
# GH #52 Task 10f) + LayerChart._build_merged encoding promotion.
# ---------------------------------------------------------------------------


def _tooltip_wire(chart) -> dict:
    spec, _data, _viewport, _theme, _cfg = chart._render_inputs(_auto_tooltips=True)
    return json.loads(spec.to_json())


def test_explicit_tooltip_on_primary_layer_does_not_leak_to_secondary(df):  # BUG: the primary layer's explicit tooltip= is promoted to the merged chart-level encoding, short-circuiting per-layer auto-injection — the secondary layer falls back to the PRIMARY's tooltip fields (the exact GH #52 Task 10f failure mode, re-entered through the lhs-explicit path)
    """Mirror of test_layered_chart_explicit_layer_tooltip_wins_over_auto but
    with the explicit tooltip on the FIRST (primary) layer: the second layer
    must still get its OWN auto tooltip_fields (x + its own y), not inherit
    the primary layer's explicit tooltip via the chart-level fallback."""
    bars = fm.Chart(df).mark_bar().encode(x="grp", y="a", tooltip="a")
    points = fm.Chart(df).mark_point().encode(x="grp", y="b")
    merged = fm.LayerChart(bars, points)._build_merged()
    kw = _tooltip_wire(merged)

    layers = kw["layers"]
    assert layers[0]["encoding"]["tooltip"] == {"field": "a"}
    # The secondary layer must carry its own fields — without them, Rust's
    # chart-level fallback shows the bar layer's tooltip on the point marks.
    assert layers[1]["encoding"].get("tooltip_fields") == [
        {"field": "grp"},
        {"field": "b"},
    ], f"secondary layer must own its tooltip fields; got {layers[1]['encoding']}"


def test_jointplot_interactive_lowering_injects_tooltips_svg_path_does_not(df):
    """_lower_composite(auto_tooltips=True) must inject tooltip_fields into
    every leaf spec while the SVG path (auto_tooltips=False) injects none —
    the composite mirror of Chart._render_scene's contract."""
    from ferrum.composition import _lower_composite

    jc = fm.jointplot(df, x="a", y="b", hue="grp")

    def leaf_specs(tree) -> list[str]:
        out: list[str] = []

        def walk(node):
            if isinstance(node, dict):
                for k, v in node.items():
                    if k == "spec" and hasattr(v, "to_json"):
                        out.append(v.to_json())
                    else:
                        walk(v)
            elif isinstance(node, list):
                for v in node:
                    walk(v)

        walk(tree)
        return out

    interactive_leaves = leaf_specs(_lower_composite(jc, auto_tooltips=True).tree)
    static_leaves = leaf_specs(_lower_composite(jc, auto_tooltips=False).tree)
    assert len(interactive_leaves) == 3
    assert all("tooltip_fields" in s for s in interactive_leaves)
    assert not any("tooltip_fields" in s for s in static_leaves)


